'use strict';

// MODULES //

var normalize = require( './normalize.js' );

/**
* Method to normalize the axis data.
*
* @private
* @name normalizeAxis
* @returns {void}
*/
function normalizeAxis() {
	var obj;
	var mxX;
	var mxZ;

	if ( !this._axisDataObj ) {
		return;
	}

	// X axis
	obj = normalize( this._axisDataObj[ 0 ].data, this._axisDataObj[ 0 ].frmt, 'graphemes' );
	mxX = obj.max;
	this._axisDataObj[ 0 ].data = obj.data;

	// Y axis
	obj = normalize( this._axisDataObj[ 1 ].data, this._axisDataObj[ 1 ].frmt, 'graphemes' );
	this._axisDataObj[ 1 ].data = obj.data;

	// Z Axis
	obj = normalize( this._axisDataObj[ 2 ].data, this._axisDataObj[ 2 ].frmt, 'graphemes' );
	mxZ = obj.max;
	this._axisDataObj[ 2 ].data = obj.data;

	// W axis
	obj = normalize( this._axisDataObj[ 3 ].data, this._axisDataObj[ 3 ].frmt, 'graphemes' );
	this._axisDataObj[ 3 ].data = obj.data;

	// Setting plot area
	this._plotArea.x = mxX;
	this._plotArea.y = 2;
	this._plotArea.z = this._plotAreaWidth + mxX;
	this._plotArea.w = 2 + this._plotAreaHeight + mxX;

	// Setting height and width for the matrix array

	// Axis tics space + plotAreaHeight
	this._height = 2 + 2 + this._plotAreaHeight;
	this._width = mxX + mxZ + this._plotAreaWidth;
}


// EXPORTS //

module.exports = normalizeAxis;
